def atoms(formula):
    tokens=re.findall(r'[A-Z][a-z]?|\d+|[()]',formula)
    assert ''.join(tokens)==formula,formula
    stack=[Counter()];i=0
    while i<len(tokens):
        token=tokens[i]
        if token=='(':stack.append(Counter());i+=1;continue
        if token==')':
            group=stack.pop();i+=1;factor=int(tokens[i])if i<len(tokens)and tokens[i].isdigit()else 1
            if i<len(tokens)and tokens[i].isdigit():i+=1
            stack[-1].update({k:v*factor for k,v in group.items()});continue
        assert token[0].isupper(),formula
        i+=1;factor=int(tokens[i])if i<len(tokens)and tokens[i].isdigit()else 1
        if i<len(tokens)and tokens[i].isdigit():i+=1
        stack[-1][token]+=factor
    assert len(stack)==1,formula
    return stack[0]

REACTIONS={}
def balance(left,right):
    molecules=[atoms(f)for f in left+right];elements=sorted(set().union(*(m.keys()for m in molecules)))
    matrix=s.Matrix([[m.get(e,0)*(1 if i<len(left)else-1)for i,m in enumerate(molecules)]for e in elements])
    kernel=matrix.nullspace();assert len(kernel)==1,(left,right)
    vector=kernel[0];scale=s.ilcm(*[v.q for v in vector]);numbers=[int(v*scale)for v in vector]
    if all(v<0 for v in numbers):numbers=[-v for v in numbers]
    divisor=reduce(math.gcd,numbers);numbers=[v//divisor for v in numbers]
    assert all(v>0 for v in numbers)and matrix*s.Matrix(numbers)==s.zeros(len(elements),1)
    REACTIONS['+'.join(left)+'->'+'+'.join(right)]=numbers
    return numbers

def oxidation(stem,rule,model,answer,calculated,options):
    task=N(stem,rule,model,answer,calculated)
    task['numericOptions']=list(map(s.sympify,options));return task

