for _level,_tasks in BANK.items():
    for _task in _tasks:
        if 'answer' in _task and s.sympify(_task['answer']).is_integer:
            if int(_level.split('.')[0])in(3,4,7,14,15)and _task.get('unit')not in('g/mol',):_task['integerOnly']=True

def format_authored(text):
    # Only the authoring bank is processed; the runtime prose normalizer is unchanged.
    pieces=text.split('$')
    for i in range(0,len(pieces),2):
        p=pieces[i]
        for plain,tex in [('Ag++e−→Ag',r'\mathrm{Ag^+}+e^-\to\mathrm{Ag}'),('Na+',r'\mathrm{Na^+}'),('Mg2+',r'\mathrm{Mg^{2+}}'),('O2−',r'\mathrm{O^{2-}}'),('Fe2+',r'\mathrm{Fe^{2+}}'),('[Ar]3d⁶4s²',r'[\mathrm{Ar}]\,3d^6 4s^2'),('[Ar]3d⁶',r'[\mathrm{Ar}]\,3d^6'),('C=O',r'\mathrm{C=O}')]:
            p=p.replace(plain,'$'+tex+'$')
        p=re.sub(r'(?<![\w\\])(?:Z|A|H|O|C|K|N|F|c|k|\[A\]|\[B\])=[+−-]?\d+(?:\.\d+)?',lambda m:'$'+m[0].replace('−','-')+'$',p)
        p=p.replace('[B] y k',r'$[B]$ y $k$')
        pieces[i]=p
    return '$'.join(pieces)

def build(write=False):
    production=ROOT/'shared/src/commonMain/composeResources/files/aprender/quimica'
    fixtures=ROOT/'shared/src/androidUnitTest/resources/composeResources/rastro.shared.generated.resources/files/aprender/quimica'
    kept=[production/'semana01/1.1/questions.json',production/'semana01/1.2/questions.json']
    hashes={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest()for p in kept}
    preview=[];proofs=[]
    for level,tasks in BANK.items():
        week,part=map(int,level.split('.'));rel=Path(f'semana{week:02}')/level/'questions.json'
        path=production/rel;old=json.loads(path.read_text(encoding='utf-8-sig'));out=[]
        assert len(tasks)==max(11,len(old)),(level,len(tasks),len(old))
        for i,task in enumerate(tasks):
            qid=f'quim_t{week:02}_s{part:02}_c{i+1:02}'
            if 'answer'in task:
                if 'numericOptions'in task:
                    values=task['numericOptions'];assert len(values)==4
                    assert len(set(values))==4 and sum(s.simplify(v-task['answer'])==0 for v in values)==1
                    shift=i%4;values=values[shift:]+values[:shift];options=[label(v,task['unit'])for v in values];key=next(j for j,v in enumerate(values)if s.simplify(v-task['answer'])==0)
                else:options,key=choices(task['answer'],task['unit'],i%4,integer_only=task.get('integerOnly',False))
                steps=[task['rule'],'Aplicamos los datos y conservamos las unidades: $'+task['model']+'$.','El resultado es '+label(task['answer'],task['unit'])+'.']
                proofs.append(dict(id=qid,model=task['model'],answer=str(task['answer']),calculated=str(task['calculated']),unit=task['unit']))
            else:
                shift=i%4;options=task['options'][shift:]+task['options'][:shift];key=(task['key']-shift)%4;steps=task['steps']
            q=dict(id=qid,concept=f'{level}.{i+1}',type='MULTIPLE_CHOICE',subject='quimica',semana=week,
                statement=format_authored(task['stem']),options=[format_authored(o)for o in options],correctIndex=key,explanation='\n'.join(f'{j+1}. {format_authored(v)}'for j,v in enumerate(steps)),
                fuente='Ejercicio original RASTRO; contraste en docs/aprender/quimica/REVISION_PRACTICA_PENDIENTE.md',pedagogicalTier='aplicación')
            out.append(q)
        assert len({q['statement']for q in out})==len(tasks),level
        assert[q['id']for q in old]==[q['id']for q in out[:len(old)]],level
        if write:
            backup=ROOT/'build/academic-backup-chemistry-pending'/rel;backup.parent.mkdir(parents=True,exist_ok=True)
            if not backup.exists():shutil.copy2(path,backup)
            path.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');assert(fixtures/rel).exists();shutil.copy2(path,fixtures/rel)
        preview.extend(out)
    assert all(hashlib.sha256((ROOT/p).read_bytes()).hexdigest()==digest for p,digest in hashes.items())
    (ROOT/'build/chemistry-pending-preview.json').write_text(json.dumps(preview,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
    (ROOT/'build/chemistry-pending-proofs.json').write_text(json.dumps(dict(levels=len(BANK),questions=len(preview),numericChecks=len(proofs),conceptualQuestions=len(preview)-len(proofs),preservedHashes=hashes,reactions=REACTIONS,proofs=proofs),ensure_ascii=False,indent=2)+'\n',encoding='utf8')
    print(json.dumps(dict(levels=len(BANK),questions=len(preview),numericChecks=len(proofs),written=write)))

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--write',action='store_true');build(parser.parse_args().write)
